export function controlEffectTargets(session: BasicGameSession, catalog: BasicGameCatalog, effect: PendingMinionTargetEffect): MinionInstance[] {
  const board = session.state.players[effect.targetPlayer].board;
  const taunt = board.some((m) => m && minionHasKeyword(session, catalog, m, "taunt"));
  return board.filter((m): m is MinionInstance => m !== null && !effect.selectedTargetIds.includes(m.instanceId)
    && targetedEffectPassesTaunt(effect.sourcePlayer, { playerId: effect.targetPlayer, kind: "minion", isTaunt: minionHasKeyword(session, catalog, m, "taunt") }, taunt));
/** Consume exhausted choices at the rules boundary, never by scanning UI logs. */
export function settlePendingEffects(session: BasicGameSession, catalog: BasicGameCatalog): void {
    const available = effect.kind === "unit"
      ? unitEffectTargets(session, catalog, effect).length
      : controlEffectTargets(session, catalog, effect).length;
    if (effect.remainingTargets > 0 && available > 0) break;
    if (effect.remainingTargets > 0) log(session, `「${effect.sourceName}」剩余效果没有合法目标，结束本次选择。`);
  if (hasPendingEffects(session)) return;


export function hasPendingEffects(session: BasicGameSession): boolean {
  return (session.pendingEffects?.length ?? 0) > 0;
}

export function currentPendingUnitEffect(session: BasicGameSession): PendingUnitEffect | null {
  const effect = session.pendingEffects?.[0];
  return effect?.kind === "unit" ? effect : null;
}

export interface UnitEffectTarget {
  key: string;
  playerId: PlayerId;
  kind: "hero" | "minion";
  instanceId?: string;
  isTaunt?: boolean;
  label: string;
  detail: string;
}

export function unitEffectTargets(session: BasicGameSession, catalog: BasicGameCatalog, effect: PendingUnitEffect): UnitEffectTarget[] {
  const result: UnitEffectTarget[] = [];
  const enemy = opponentOf(effect.sourcePlayer);
  const enemyTaunt = session.state.players[enemy].board.some((m) => m && minionHasKeyword(session, catalog, m, "taunt"));
  const accept = (target: UnitEffectTarget): void => {
    if (!(effect.action === "attack_buff" && target.kind === "hero") && !effect.selectedKeys.includes(target.key) && scopeAllowsTarget(effect.sourcePlayer, effect.scope, target)
      && targetedEffectPassesTaunt(effect.sourcePlayer, target, enemyTaunt)) result.push(target);
  };
  for (const playerId of ["P1", "P2"] as const) {
    const side = session.state.players[playerId];
    accept({ key: `hero:${playerId}`, playerId, kind: "hero", label: playerName(playerId), detail: `♥ ${side.health}` });
    side.board.forEach((m, index) => {
      if (!m) return;
      accept({
        key: `minion:${m.instanceId}`, playerId, kind: "minion", instanceId: m.instanceId,
        isTaunt: minionHasKeyword(session, catalog, m, "taunt"), label: cardName(m.cardId, catalog),
        detail: `${index + 1}号位 · ⚔ ${getAttack(m, catalog)} · ♥ ${m.currentHealth}`
      });
    });
  }
  return result;
}

/** The same damage, death and deathrattle pipeline serves all target choices. */
export function chooseUnitEffectTarget(session: BasicGameSession, catalog: BasicGameCatalog, effectId: string, key: string): string | null {
  const effect = currentPendingUnitEffect(session);
  if (!effect || effect.id !== effectId) return "待结算效果已变化，请重新选择。";
  const target = unitEffectTargets(session, catalog, effect).find((entry) => entry.key === key);
  if (!target) return "这个目标当前不合法。";
  if (target.kind === "hero") {
    const hero = session.state.players[target.playerId];
    hero.health += effect.action === "heal" ? effect.amount : -effect.amount;
  } else {
    const found = findBoardMinion(session, target.playerId, target.instanceId!);
    if (!found) return "目标已经离场。";
    if (effect.action === "heal") found.minion.currentHealth += effect.amount;
    else if (effect.action === "attack_buff") found.minion.attackModifier += effect.amount;
    else {
      if (effect.action === "damage") applyDamageToMinion(session, found.minion, effect.amount, catalog);
      else found.minion.currentHealth -= effect.amount;
      if (found.minion.currentHealth <= 0) killMinion(session, target.playerId, found.slotIndex, effect.action === "damage" ? "damage" : "other", catalog);
    }
  }
  log(session, `「${effect.sourceName}」亡语对「${target.label}」完成结算。`);
  effect.selectedKeys.push(key);
  effect.remainingTargets -= 1;
  if (effect.remainingTargets <= 0 || unitEffectTargets(session, catalog, effect).length === 0) session.pendingEffects!.shift();
  settlePendingEffects(session, catalog);
  resolveWinner(session);
  touch(session);
  return null;
}

import type { CardId } from "../model/cards.js";
import { attackHero, attackMinion, choosePendingEffectTarget, chooseUnitEffectTarget, endTurn, revealCurrentTurn, summonFromHand, type BasicGameCatalog, type BasicGameSession } from "./basic-game.js";
import { summonIntoSacrificedSlot } from "./sacrifice-placement.js";

export type GameCommand =
  | { type: "summon"; handIndex: number; slotIndex: number; cardId: CardId; sacrifices?: string[] }
  | { type: "sacrifice-summon"; handIndex: number; cardId: CardId; sacrifices: string[] }
  | { type: "attack-minion"; attackerId: string; targetId: string }
  | { type: "attack-hero"; attackerId: string }
  | { type: "end-turn" }
  | { type: "reveal-turn" }
  | { type: "choose-control"; effectId: string; targetId: string }
  | { type: "choose-unit"; effectId: string; targetKey: string };

/** All browser gameplay actions enter the same pure rules boundary. */
export function applyCommand(session: BasicGameSession, catalog: BasicGameCatalog, command: GameCommand): string | null {
  if (command.type === "summon" || command.type === "sacrifice-summon") {
    if (session.state.players[session.state.activePlayer].hand[command.handIndex] !== command.cardId) return "手牌已变化，请重新选择。";
  }
  switch (command.type) {
    case "summon": return summonFromHand(session, catalog, command.handIndex, command.slotIndex, command.sacrifices ?? []);
    case "sacrifice-summon": return summonIntoSacrificedSlot(session, catalog, command.handIndex, command.sacrifices);
    case "attack-minion": return attackMinion(session, catalog, command.attackerId, command.targetId);
    case "attack-hero": return attackHero(session, catalog, command.attackerId);
    case "end-turn": return endTurn(session);
    case "reveal-turn":
      if (session.state.winner) return "对局已经结束。";
      if (!session.handoffRequired) return "本回合已经开始。";
      revealCurrentTurn(session); return null;
    case "choose-control": return choosePendingEffectTarget(session, catalog, command.targetId, command.effectId);
    case "choose-unit": return chooseUnitEffectTarget(session, catalog, command.effectId, command.targetKey);
  }
}

import type { CardId, MinionCardDefinition } from "../model/cards.js";
import type { PlayerId } from "../model/state.js";
import type { UnitTargetScope } from "./unit-targeting.js";

export interface PendingUnitEffect {
  id: string;
  kind: "unit";
  sourcePlayer: PlayerId;
  sourceCardId: CardId;
  sourceName: string;
  action: "damage" | "health_loss" | "heal" | "attack_buff";
  amount: number;
  scope: UnitTargetScope;
  remainingTargets: number;
  selectedKeys: string[];
  text: string;
}

export function parseUnitDeathrattle(
  card: MinionCardDefinition,
  sourcePlayer: PlayerId,
  rawText: string,
  id: string,
): PendingUnitEffect | null {
  const text = rawText.replace(/[。.]$/, "").replace(/\s+/g, "").trim();
  let match = text.match(/^死后对选中(单位|随从)造成(\d+)点伤害$/);
  if (match) return makePending(id, card, sourcePlayer, "damage", Number(match[2]), scopeFromNoun(match[1]!), 1, text);

  match = text.match(/^死后对(?:两个|两(?:个)?|2个)(单位|随从)各造成(\d+)点伤害$/);
  if (match) return makePending(id, card, sourcePlayer, "damage", Number(match[2]), scopeFromNoun(match[1]!), 2, text);

  match = text.match(/^死后选择一个(单位|随从)[，,]?扣(\d+)(?:点)?血$/);
  if (match) return makePending(id, card, sourcePlayer, "health_loss", Number(match[2]), scopeFromNoun(match[1]!), 1, text);

  match = text.match(/^死后选取(?:两个|两(?:个)?|2个)(单位|随从)[，,]?各扣(\d+)点血$/);
  if (match) return makePending(id, card, sourcePlayer, "health_loss", Number(match[2]), scopeFromNoun(match[1]!), 2, text);

  match = text.match(/^死后选定一个(单位|随从)加(\d+)血$/);
  if (match) return makePending(id, card, sourcePlayer, "heal", Number(match[2]), scopeFromNoun(match[1]!), 1, text);

  match = text.match(/^死后给指定随从加(\d+)攻击$/);
  if (match) return makePending(id, card, sourcePlayer, "attack_buff", Number(match[1]), "all_minions", 1, text);

  return null;
}

function makePending(
  id: string,
  card: MinionCardDefinition,
  sourcePlayer: PlayerId,
  action: PendingUnitEffect["action"],
  amount: number,
  scope: UnitTargetScope,
  remainingTargets: number,
  text: string,
): PendingUnitEffect {
  return {
    id,
    kind: "unit",
    sourcePlayer,
    sourceCardId: card.id,
    sourceName: card.name,
    action,
    amount,
    scope,
    remainingTargets,
    selectedKeys: [],
    text,
  };
}

function scopeFromNoun(noun: string): UnitTargetScope {
  return noun === "随从" ? "all_minions" : "all_units";
}

import { summonFromHand, type BasicGameCatalog, type BasicGameSession } from "./basic-game.js";
/** Fixed five-slot board: sacrifice placement is validated by the core command. */
export function summonIntoSacrificedSlot(session: BasicGameSession, catalog: BasicGameCatalog, handIndex: number, ids: string[]): string | null {
  const sacrifices = [...new Set(ids)];
  const board = session.state.players[session.state.activePlayer].board;
  const slots = sacrifices.map((id) => board.findIndex((m) => m?.instanceId === id));
  if (slots.some((slot) => slot < 0)) return "献祭目标必须仍在己方场上。";
  return summonFromHand(session, catalog, handIndex, Math.min(...slots), sacrifices);

